// Exam-bank questions for Data Preparation (9%). Not reused in lesson checks or the module quiz.
export default [
  { id: 'xd01', domain: 'data',
    scenario: 'A company wants to fine-tune an open model to call internal tools using new markers `<call>` and `</call>`. They add both strings to the tokenizer as special tokens and start LoRA training on attention projections only. At inference the model never emits the markers.',
    q: 'What is the most likely problem?',
    opts: [
      'Special tokens cannot be generated by decoder-only models',
      'The chat template must be removed when new tokens are added',
      'The embeddings were not resized and/or the new embedding and LM-head rows were never trained',
      'LoRA requires the vocabulary to be a multiple of 64',
    ],
    a: 2,
    why: 'New tokens need `resize_token_embeddings` and trainable embedding/LM-head rows. With LoRA on attention only, those rows stay at their initial values, so the model has no reason to produce them.',
    distract: 'Decoder models emit special tokens all the time (EOS, end-of-turn). The chat template stays. Padding the vocabulary to a multiple of 64 is a performance nicety, not a LoRA requirement.' },

  { id: 'xd02', domain: 'data',
    q: 'Which ordering of a web-scale pretraining curation pipeline is most cost-effective?',
    opts: [
      'Text extraction → language ID → heuristic filters → exact then fuzzy dedup → model-based quality filtering → PII redaction and decontamination → mixing',
      'Model-based quality filtering → text extraction → fuzzy dedup → language ID → heuristic filters → mixing',
      'Fuzzy dedup on raw HTML → language ID → text extraction → heuristic filters → mixing',
      'Mixing → tokenisation → language ID → dedup → heuristic filters',
    ],
    a: 0,
    why: 'Cheap, high-volume steps (extraction, language ID, heuristics, exact dedup) come first so the expensive ones (fuzzy dedup, neural classifiers) process less data; mixing and tokenisation come last.',
    distract: 'Running neural classifiers or fuzzy dedup first wastes compute on data that cheap filters would drop. Deduplicating raw HTML is dominated by markup noise. Mixing before filtering locks in weights for data you will later remove.' },

  { id: 'xd03', domain: 'data',
    scenario: 'A data engineer’s fuzzy dedup with MinHash LSH (threshold ≈ 0.7) removes many documents that are clearly different articles sharing a long cookie banner and footer.',
    q: 'Which change best addresses this?',
    opts: [
      'Switch to exact MD5 deduplication only',
      'Lower the LSH threshold to 0.5',
      'Use fewer rows per band',
      'Strip boilerplate (banners, footers, navigation) during text extraction before computing shingles',
    ],
    a: 3,
    why: 'The shared boilerplate inflates Jaccard similarity between unrelated articles. Removing it during extraction makes shingles reflect the main content, so [[minhash|MinHash]] similarity becomes meaningful.',
    distract: 'Exact dedup would stop removing true near-duplicates. Lowering the threshold or using fewer rows per band makes LSH **more** permissive, removing even more unrelated documents.' },

  { id: 'xd04', domain: 'data',
    q: 'A team’s tokenizer produces 3.2× more tokens for Hindi than for English on parallel text. They plan to serve Hindi users heavily. Which option most directly reduces the cost?',
    opts: [
      'Lower the sampling temperature',
      'Choose a base model whose tokenizer was trained with substantial Hindi data (or a larger multilingual vocabulary)',
      'Increase the context window',
      'Enable packing during inference',
    ],
    a: 1,
    why: 'Token count per sentence is fixed by the tokenizer’s [[vocabulary]]. A tokenizer trained on balanced multilingual data compresses Hindi better, cutting tokens, latency and cost per request.',
    distract: 'Temperature changes sampling, not token counts. A longer context window holds more tokens but does not reduce how many are needed. Packing is a training-time batching technique.' },

  { id: 'xd05', domain: 'data',
    scenario: 'An SFT run uses RAG-style examples: each prompt contains ~1,500 tokens of retrieved documents and the answers average 80 tokens. Loss is computed on all tokens. The model learns the answer style slowly.',
    q: 'What change best focuses training on the desired behaviour?',
    opts: [
      'Increase the number of retrieved documents per prompt',
      'Disable the attention mask on the retrieved documents',
      'Mask the prompt and retrieved context out of the loss (labels = −100) so gradients come from the answers',
      'Convert the dataset to a single-turn Alpaca format without changing the loss',
    ],
    a: 2,
    why: 'With 1,500 context tokens and 80 answer tokens, ~95% of the loss is spent predicting retrieved text. [[loss-masking|Loss masking]] concentrates learning on the responses the model must actually produce.',
    distract: 'More documents worsen the imbalance. Dropping the attention mask breaks the model’s view of its context. Changing the data format does not change which tokens are scored.' },

  { id: 'xd06', domain: 'data',
    q: 'A team generates 500k synthetic instruction-response pairs with a large teacher model. Which step is most important before fine-tuning on them?',
    opts: [
      'Upsample the shortest responses so training is faster',
      'Remove all human-written examples to keep the style consistent',
      'Train for more epochs to compensate for synthetic noise',
      'Filter with a reward model, LLM judge or execution checks, deduplicate, decontaminate against eval sets, and confirm the teacher’s licence allows this use',
    ],
    a: 3,
    why: '[[synthetic-data|Synthetic data]] quality varies widely; filtering, dedup and [[data-contamination|decontamination]] determine whether it helps, and some model licences restrict training other models on their outputs.',
    distract: 'Favouring short responses biases the model toward terse answers. Dropping human data reduces diversity and invites model collapse. More epochs on noisy data increases memorisation of errors.' },
]
